// Golden master of the Orders HTTP API as it behaves today. Contract: test/orders-contract.yaml
// Pricing downstream is an in-process hand-written fake injected into the app (mocking: inprocess).
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 10.5, gold: 120, hundred: 100, odd: 101 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order: 201, string id, total without discount at or below 100', async () => {
  const r = await json(await post({ items: [{ sku: 'apple', qty: 2 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body, { id: r.body.id, items: [{ sku: 'apple', qty: 2 }], total: 20 })
})

test('POST /orders asks pricing once per item and sums price*qty', async () => {
  calls.length = 0
  const r = await json(await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 2 }] }))
  assert.deepEqual(calls, ['apple', 'pear'])
  assert.equal(r.body.total, 31)
})

test('POST /orders truncates the total to an integer (floor, not round)', async () => {
  const r = await json(await post({ items: [{ sku: 'pear', qty: 3 }] }))
  assert.equal(r.body.total, 31) // 31.5
})

test('POST /orders: exactly 100 gets no discount', async () => {
  const r = await json(await post({ items: [{ sku: 'hundred', qty: 1 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders: totals above 100 get 10% off, then floor', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'gold', qty: 1 }] }))).body.total, 108)
  assert.equal((await json(await post({ items: [{ sku: 'odd', qty: 1 }] }))).body.total, 90) // 90.9
})

test('POST /orders ids increase by one per created order', async () => {
  const a = (await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body.id
  const b = (await json(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('POST /orders rejects missing, empty, non-array items and bad JSON with 400', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{nope'), await post(null, 'null')]) {
    const r = await json(res)
    assert.equal(r.status, 400)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'items required' })
  }
})

test('POST /orders with an empty body is a 400', async () => {
  const r = await json(await fetch(`${base}/orders`, { method: 'POST' }))
  assert.deepEqual([r.status, r.body], [400, { error: 'items required' }])
})

test('POST /orders does not validate items: non-numeric qty gives total null, still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no item validation; NaN total serialises as null
  const r = await json(await post({ items: [{ sku: 'apple', qty: 'abc' }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders coerces numeric-string qty', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "2" is multiplied as a number
  const r = await json(await post({ items: [{ sku: 'apple', qty: '2' }] }))
  assert.equal(r.body.total, 20)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = (await json(await post({ items: [{ sku: 'gold', qty: 1 }] }))).body
  const r = await json(await fetch(`${base}/orders/${created.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('GET /orders/:id for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const r = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.deepEqual([r.status, r.body], [200, { error: 'not found' }])
})

test('unmatched routes and methods answer 404 {error:"no route"}', async () => {
  const cases = [
    fetch(`${base}/`), fetch(`${base}/nope`), fetch(`${base}/orders`), fetch(`${base}/orders/`),
    fetch(`${base}/orders/1/extra`), fetch(`${base}/orders/1`, { method: 'DELETE' }), fetch(`${base}/orders/1`, { method: 'PUT', body: '{}' }),
  ]
  for (const res of cases) {
    const r = await json(await res)
    assert.deepEqual([r.status, r.type, r.body], [404, 'application/json', { error: 'no route' }])
  }
})
